def add_person(person):
    if type(person) is not dict:
        return
    if 'tickets' not in person:
        person['tickets'] = []
    default_person = {'age': 18, 'race': 'white'}
    for key in default_person:
        if key not in person:
            person[key] = default_person[key]
    return person

def merge_arrays(arr1, arr2):
    merged = []
    i, j = 0, 0
    while i < len(arr1) and j < len(arr2):
        if arr1[i] < arr2[j]:
            merged.append(arr1[i])
            i += 1
        else:
            merged.append(arr2[j])
            j += 1
    while i < len(arr1):
        merged.append(arr1[i])
        i += 1
    while j < len(arr2):
        merged.append(arr2[j])
        j += 1
    return merged

def main():
    arr1 = [1, 5, 7, 12, 25, 33]
    arr2 = [2, 8, 9, 18, 33, 35, 40]
    merged = merge_arrays(arr1, arr2)
    print("Merged array:", merged)

if __name__ == '__main__':
    main()

