@app.route('/', methods=['GET', 'POST'])
def index():
    if request.method == 'POST':
        sentence = request.form['sentence']
        sentence = request.form['sentence']

        prompt = f"Generate a sentence with similar meaning to: {sentence}"

        response = openai.Completion.create(
            engine="text-davinci-002",
            prompt=prompt,
            max_tokens=50,
            n=1,
            stop=None,
            temperature=0.5,
        )

        paraphrase = response.choices[0].text.strip()

        return render_template('index.html', paraphrase=paraphrase)

    return render_template('index.html', paraphrase=None)

