from flask import Flask, request
import tensorflow as tf

app = Flask(__name__)

def load_model():
    model = tf.keras.models.load_model('my_model.h5')
    return model

@app.route('/predict', methods=['POST'])
def predict():
    img_data = request.get_json()['img']
    img_2d = tf.keras.preprocessing.image.img_to_array(img_data)
    img_3d = tf.expand_dims(img_2d, axis=2)

    model = load_model()
    prediction = model.predict(img_3d)
    return {'predicted_class': str(prediction)}

if __name__ == '__main__':
    app.run()

from flask import Flask, request
import re

