@app.route('/report', methods=['POST'])
def report():
    data = request.json
    user = data['user']
    issues = data['issues']
    report = {
        'user': user,
        'date': datetime.utcnow(),
        'issues': issues
    }
    added = mongo.db.report.insert_one(report)
    return jsonify({'id': str(added.inserted_id)})

@app.route('/report/<report_id>', methods=['PUT'])
def update(report_id):
    data = request.json
    action = mongo.db.report.update_one({'_id': ObjectId(report_id)}, {'$set': data})
    return jsonify({'status': 'OK'})

